def balance_bst(root):
    vals = []
    def inorder(node):
        if node:
            inorder(node.left); vals.append(node.val); inorder(node.right)
    inorder(root)                                        # flatten to sorted values

    def build(l, r):
        if l > r:
            return None
        mid = (l + r) // 2                                # middle as root
        return TreeNode(vals[mid], build(l, mid - 1), build(mid + 1, r))

    return build(0, len(vals) - 1)

