public class Main {
    static List<Integer> vals = new ArrayList<>();
    static TreeNode balanceBST(TreeNode root) {
        inorder(root);                                        // flatten to sorted values
        return build(0, vals.size() - 1);
    }
    static void inorder(TreeNode node) {
        if (node == null) return;
        inorder(node.left); vals.add(node.val); inorder(node.right);
    }
    static TreeNode build(int l, int r) {
        if (l > r) return null;
        int mid = (l + r) / 2;                                  // middle as root
        TreeNode root = new TreeNode(vals.get(mid));
        root.left = build(l, mid - 1);
        root.right = build(mid + 1, r);
        return root;
    }
}

